INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die ABC-Analyse nur für Lagerbestände geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Kunden oder Projekte nutzbar"}, {"text": "Ja", "correct": false, "because": "Nicht auf Lager beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorie hat den höchsten Wert in der Analyse?', 3, '[{"text": "A", "correct": true, "because": "80% des Werts, 20% der Menge"}, {"text": "B", "correct": false, "because": "Mittlere Priorität"}, {"text": "C", "correct": false, "because": "Geringster Wert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale gehören zur A-Kategorie?', 5, '[{"text": "Hoher Wert", "correct": true, "because": "Wirtschaftlich entscheidend"}, {"text": "Geringe Menge", "correct": true, "because": "Pareto-Prinzip"}, {"text": "Hohe Stückzahl", "correct": false, "because": "Typisch für C"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) A-Artikel brauchen strenge Kontrolle. b) C-Artikel sind immer unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "C-Artikel haben geringen Wert, aber nicht unwichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Priorisierung?', 4, '[{"text": "Umsatzanteil", "correct": false, "because": "Kern der Analyse"}, {"text": "Mengenanteil", "correct": false, "because": "Definiert Kategorien"}, {"text": "Farbe der Produkte", "correct": true, "because": "Irrelevant für Wert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Analyse auf Pareto basiert?', 2, '[{"text": "Ja", "correct": true, "because": "80/20-Regel"}, {"text": "Nein", "correct": false, "because": "Grundprinzip ist Pareto"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorie umfasst die meisten Elemente?', 3, '[{"text": "C", "correct": true, "because": "80% der Menge, geringer Wert"}, {"text": "A", "correct": false, "because": "Wenige, aber wertvoll"}, {"text": "B", "correct": false, "because": "Mittlere Menge"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur B-Kategorie?', 5, '[{"text": "Mittlerer Wert", "correct": true, "because": "Zwischen A und C"}, {"text": "Mittlere Menge", "correct": true, "because": "Moderate Relevanz"}, {"text": "Maximale Kontrolle", "correct": false, "because": "Eher bei A"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ABC-Analyse spart Zeit. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Firmen nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse unwichtig?', 4, '[{"text": "Wertanteil", "correct": false, "because": "Kernkriterium"}, {"text": "Mengenverteilung", "correct": false, "because": "Definiert Kategorien"}, {"text": "Lieferantenhistorie", "correct": true, "because": "Sekundär für ABC"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat A immer die wenigsten Elemente?', 2, '[{"text": "Ja", "correct": true, "because": "20% Menge, 80% Wert"}, {"text": "Nein", "correct": false, "because": "Typisch für A"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt die Methode?', 4, '[{"text": "Effiziente Ressourcennutzung", "correct": true, "because": "Fokus auf A"}, {"text": "Weniger Kontrolle bei C", "correct": true, "because": "Geringerer Aufwand"}, {"text": "Gleichmäßige Verteilung", "correct": false, "because": "Nicht das Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Analyse nur Umsatz berücksichtigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Menge entscheidend"}, {"text": "Ja", "correct": false, "because": "Nicht allein Umsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Analyse?', 3, '[{"text": "Wertbeitrag", "correct": true, "because": "Definiert Kategorien"}, {"text": "Gleichmäßigkeit", "correct": false, "because": "Nicht das Ziel"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Genauigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) B-Artikel sind Übergang. b) C-Artikel brauchen keine Kontrolle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "C braucht minimale Kontrolle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Methode?', 5, '[{"text": "Vernachlässigung von C", "correct": true, "because": "Kann langfristig schaden"}, {"text": "Subjektive Grenzen", "correct": true, "because": "Kategorien flexibel"}, {"text": "Zu einfache Umsetzung", "correct": false, "because": "Nicht trivial"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der C-Kategorie unwichtig?', 3, '[{"text": "Geringer Wert", "correct": false, "because": "Definiert C"}, {"text": "Hohe Menge", "correct": false, "because": "Typisch für C"}, {"text": "Strenge Kontrolle", "correct": true, "because": "Aufwand nicht gerechtfertigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Analyse dynamisch?', 3, '[{"text": "Ja", "correct": true, "because": "Muss regelmäßig angepasst werden"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Analyse auch für IT-Projekte passt?', 2, '[{"text": "Ja", "correct": true, "because": "Priorisierung universell"}, {"text": "Nein", "correct": false, "because": "Nicht branchenspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorie wähle ich für Schlüsselprodukte?', 4, '[{"text": "A", "correct": true, "because": "Hoher Wert, hohe Priorität"}, {"text": "B", "correct": false, "because": "Mittlere Relevanz"}, {"text": "C", "correct": false, "because": "Geringer Fokus"}]');
